const structureVariant = (x, y, i) => (i * 3 + x + y) % 4 + 1; // 그림 고르기: 이웃한 건물끼리 다른 색 지붕이 되게
function structuresIn(def) {
  const rows = def.art, seen = new Set(), list = [];
  rows.forEach((r, y) => [...r].forEach((c, x) => { const t = STRUCTURE_TYPES[c]; if (!t || seen.has(`${x},${y}`)) return; for (let yy = y; yy < y + t.h; yy++) for (let xx = x; xx < x + t.w; xx++) seen.add(`${xx},${yy}`); list.push({ kind: t.kind, v: structureVariant(x, y, list.length), i: list.length, room: `${t.kind}${list.length}` }); }));
  return list;
}
for (const def of MAPS) if (def.kind === 'town') ROOM_DEFS.push(...structureRooms(def.zone, structuresIn(def)));
export const MAP_BY_ID = Object.fromEntries([...MAPS, STARTER_MEADOW, ...ROOM_DEFS].map(m => [m.id, m]));
export const townId = zone => `town${zone}`;
export const routeId = index => `route${index}`;
export function getMapDef(id) { return MAP_BY_ID[typeof id === 'number' ? townId(id) : id] || MAP_BY_ID.town0; }
export function nextMapId(id) { const i = MAPS.findIndex(m => m.id === id); return MAPS[i + 1]?.id || null; }
export function prevMapId(id) { const i = MAPS.findIndex(m => m.id === id); return i > 0 ? MAPS[i - 1].id : null; }

// The most common land terrain among the four neighbours; exits/spawns look inward along the row.
function inferBase(rows, x, y) {
  if ('<>az'.includes(rows[y][x])) {
    const mw = rows[y].length, dir = x < mw / 2 ? 1 : -1;
    for (let i = x + dir; i >= 0 && i < mw; i += dir) { const c = rows[y][i]; if (c in TERRAIN && c !== '~') return c; }
  }
  const count = {};
  for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
    const c = rows[y + dy]?.[x + dx];
    if (c in TERRAIN && c !== '~') count[c] = (count[c] || 0) + 1;
  }
  const order = ['=', '.', ':', '"', '#'];
  const best = Object.keys(count).sort((a, b) => count[b] - count[a] || order.indexOf(a) - order.indexOf(b))[0];
  if (best) return best;
  // Enclosed (e.g. the middle of a rock cluster): use the nearest terrain in growing rings.
  for (let r = 2; r <= 8; r++) for (let dy = -r; dy <= r; dy++) for (let dx = -r; dx <= r; dx++) {
    if (Math.max(Math.abs(dx), Math.abs(dy)) !== r) continue;
    const c = rows[y + dy]?.[x + dx]; if (c in TERRAIN) return c;
  }
  return '~';
}

const parsed = new Map();
export function forgetParsed(id) { parsed.delete(id); } // 검사·도구용: 지도 정의를 바꾼 뒤 다시 읽어요

// v0.70 높낮이: def.heights 의 네모 칸들이 한 층 높은 언덕(층 1)이에요.
//   언덕 남쪽 아래 한 줄 = 절벽 면(face) · 언덕 안쪽의 북·동·서 가장자리 = 바위 턱(rim). 둘 다 지나갈 수 없어요.
//   길(=)이 절벽 면이나 바위 턱을 지나는 칸은 저절로 계단이 되고, def.ladders 의 절벽 면 칸은 사다리예요.
//   그래서 위아래는 계단·사다리로만 오가요(걷기·길 찾기·우산몬·사람 모두 막힌 칸 규칙 그대로).
//   level: 칸 → 높이(언덕 1, 계단·사다리 0.5) · cliff: { face, rim(칸 → 'nwe' 중 열린 쪽), stairs, ladders }
// v0.74 여러 층: heights 네모에 lv(2~9)를 주거나, def.levels(지도와 같은 30줄, 칸마다 0~9 숫자 · 그 밖의 글자는 0)로 층을 그려요.
//   층이 높아질수록 한 칸씩 물러나게 그리면 계단식 절벽(울릉도 산·독도 절벽)이 돼요. 한 층 = 절벽 면 한 줄.
//   계단은 위·아래 층 가운데 높이(예: 1층↔2층 계단은 1.5).
function applyHeights(out, def) {
  const L = new Map(), K = (x, y) => `${x},${y}`;
  for (const r of def.heights || []) for (let y = r.y0; y <= r.y1; y++) for (let x = r.x0; x <= r.x1; x++) L.set(K(x, y), Math.max(L.get(K(x, y)) || 0, r.lv || 1));
  (def.levels || []).forEach((row, y) => [...row].forEach((c, x) => { const v = '0123456789'.indexOf(c); if (v > 0) L.set(K(x, y), Math.max(L.get(K(x, y)) || 0, v)); }));
  const lv = (x, y) => L.get(K(x, y)) || 0, R = new Set(L.keys());
  const level = new Map(), face = new Set(), faceTop = new Map(), rim = new Map(), stairs = new Set(), ladders = new Set();
  const path = (x, y) => out.grid[y]?.[x] === TILE_CODES.PATH || out.ground.some(g => g.kind === 'steps' && g.x === x && g.y === y);
  for (const [k, v] of L) {
    const [x, y] = k.split(',').map(Number); level.set(k, v);
    if (lv(x, y + 1) < v && y + 1 < out.grid.length) { const f = K(x, y + 1); face.add(f); faceTop.set(f, Math.max(faceTop.get(f) || 0, v)); }
    const sides = (lv(x, y - 1) < v ? 'n' : '') + (lv(x - 1, y) < v ? 'w' : '') + (lv(x + 1, y) < v ? 'e' : '');
    if (sides) rim.set(k, sides);
  }
  for (const k of face) { const [x, y] = k.split(',').map(Number); if (path(x, y) && !out.solid.has(k)) stairs.add(k); }
  for (const k of rim.keys()) { const [x, y] = k.split(',').map(Number); if (path(x, y) && !out.solid.has(k) && !face.has(k)) stairs.add(k); }
  for (const [x, y] of def.ladders || []) if (face.has(K(x, y))) ladders.add(K(x, y));
  for (const k of face) { const [x, y] = k.split(',').map(Number); if (!stairs.has(k) && !ladders.has(k)) out.solid.add(k); else level.set(k, (faceTop.get(k) + lv(x, y)) / 2); }
  for (const [k, sides] of rim) {
    if (face.has(k)) continue; const [x, y] = k.split(',').map(Number), v = lv(x, y);
    if (!stairs.has(k)) { out.solid.add(k); continue; }
    const low = Math.min(...[...sides].map(s => s === 'n' ? lv(x, y - 1) : s === 'w' ? lv(x - 1, y) : lv(x + 1, y))); level.set(k, (v + low) / 2);
  }
  out.level = level; out.cliff = { face, faceTop, rim, stairs, ladders, region: R, base: L, top: Math.max(0, ...L.values()) }; // base: 칸마다 땅이 놓인 층(3D 땅·벽)
}
// Returns the tile grid (array of rows of tile codes) plus the map's objects.
export function parseMap(id) {
  const def = getMapDef(id);
  if (parsed.has(def.id)) return parsed.get(def.id);
  const rows = def.art;
  // v0.74 지도마다 크기가 달라도 돼요(가장 작게 42×30, 건물 안은 42×30). 줄마다 너비는 같아야 해요.
  const MW = rows[0]?.length || 0, MH = rows.length;
  if (MH < MAP_H || MW < MAP_W || rows.some(r => r.length !== MW) || (def.kind === 'room' && (MW !== MAP_W || MH !== MAP_H))) throw new Error(`${def.id}: map must be at least ${MAP_W}x${MAP_H} with equal rows`);
  if (def.kind === 'room') { const out = parseRoom(def); parsed.set(def.id, out); return out; }
  const grid = rows.map(() => Array(MW).fill(0));
  const out = { def, grid, solid: new Set(), exits: new Map(), spawns: {}, buildings: [], structures: [], decor: [], ground: [], roles: {}, residents: {}, objects: [] };
  const seenBuilding = new Set();
  const rocks = [];
  for (let y = 0; y < MH; y++) for (let x = 0; x < MW; x++) {
    const c = rows[y][x], key = `${x},${y}`;
    if (c in TERRAIN) { grid[y][x] = TERRAIN[c]; continue; }
    if (c in GROUND) {
      const [base, kind] = GROUND[c]; grid[y][x] = TERRAIN[base];
      if (kind !== 'helipad' || (rows[y][x - 1] !== 'K' && rows[y - 1]?.[x] !== 'K')) out.ground.push({ kind, x, y });
      continue;
    }
    if (c in STRUCTURE_TYPES) { // v0.74 (지나갈 수 없고 문도 없어요)
      grid[y][x] = TILE_CODES.BUILDING;
      if (!seenBuilding.has(key)) {
        const t = STRUCTURE_TYPES[c];
        for (let yy = y; yy < y + t.h; yy++) for (let xx = x; xx < x + t.w; xx++) { seenBuilding.add(`${xx},${yy}`); if (rows[yy]?.[xx] !== c) throw new Error(`${def.id}: structure '${c}' at ${x},${y} must be ${t.w}x${t.h}`); }
        const i = out.structures.length, v = structureVariant(x, y, i), room = `${t.kind}${i}`;
        out.structures.push({ x, y, w: t.w, h: t.h, name: structurePlan(t.kind, v, i).title, kind: t.kind, v, i, room }); // v0.75 들어가 볼 수 있어요(room: 건물 안 지도 이름)
      }
      continue;
    }
    if (c in BUILDING_TYPES) {
      grid[y][x] = TILE_CODES.BUILDING;
      if (!seenBuilding.has(key)) {
        const t = BUILDING_TYPES[c];
        for (let yy = y; yy < y + t.h; yy++) for (let xx = x; xx < x + t.w; xx++) seenBuilding.add(`${xx},${yy}`);
        out.buildings.push({ x, y, w: t.w, h: t.h, name: t.name, color: t.color, kind: t.kind });
      }
      continue;
    }
    const base = c === 'b' || c === 'x' || c === 'F' ? '~' : inferBase(rows, x, y); // 배·소파블록은 물 위
    grid[y][x] = TERRAIN[base];
    if (c in DECOR) {
      if (c === 'M') { grid[y][x] = TILE_CODES.MONUMENT; if (rows[y][x - 1] !== 'M') out.decor.push({ kind: 'monument', x, y }); continue; }
      if (c !== 'b' && c !== 'F') out.solid.add(key);
      if (c === 'f') { if (rows[y][x - 1] !== 'f') { let len = 0; while (rows[y][x + len] === 'f') len++; out.decor.push({ kind: 'fence', x, y, len }); } continue; }
      if (c === 'r') { rocks.push([x, y]); continue; }
      if (c === 'k') { // v0.74 쇠 난간: 가로로 이어지면 판 하나, 세로로만 이어지면 칸마다 기둥
        if (rows[y][x - 1] !== 'k') { let len = 0; while (rows[y][x + len] === 'k') len++; if (len > 1) out.decor.push({ kind: 'rail', x, y, len }); }
        if (rows[y][x - 1] !== 'k' && rows[y][x + 1] !== 'k') out.decor.push({ kind: 'railv', x, y });
        continue;
      }
      out.decor.push({ kind: DECOR[c], x, y });
      continue;
    }
    if (c === '<' || c === '>') { out.exits.set(key, c === '<' ? 'prev' : 'next'); continue; }
    if (c === 'a' || c === 'z') { out.spawns[c] = { x, y }; continue; }
    if (def.kind === 'town' && c in TOWN_ROLES) { out.roles[TOWN_ROLES[c]] = { x, y }; continue; }
    if (def.kind === 'town' && '12345'.includes(c)) { out.residents[c] = { x, y }; continue; }
    if (/[0-9]/.test(c) && def.objects?.[c]) { out.objects.push({ key: c, x, y, ...def.objects[c] }); continue; }
    throw new Error(`${def.id}: unknown map letter '${c}' at ${x},${y}`);
  }
  // Rocks: lone stones are props; clusters become textured outcrops, and solid big ones get a peak.
  out.rockTiles = new Set();
  const rockSet = new Set(rocks.map(p => p.join(','))), done = new Set();
  for (const start of rocks) {
    const k0 = start.join(','); if (done.has(k0)) continue;
    const comp = [], queue = [start]; done.add(k0);
    while (queue.length) {
      const [x, y] = queue.pop(); comp.push([x, y]);
      for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) { const k = `${x + dx},${y + dy}`; if (rockSet.has(k) && !done.has(k)) { done.add(k); queue.push([x + dx, y + dy]); } }
    }
    if (comp.length < 3) { for (const [x, y] of comp) out.decor.push({ kind: 'rock', x, y }); continue; }
    // v0.76 한 덩어리 바위의 바닥은 하나로: 물 위 칸과 땅 위 칸이 섞이면 물가 거품 테두리가 바위 안에 생겨요
    const landBase = comp.map(([x, y]) => grid[y][x]).find(t => t !== 0); if (landBase !== undefined) for (const [x, y] of comp) if (grid[y][x] === 0) grid[y][x] = landBase;
    for (const [x, y] of comp) out.rockTiles.add(`${x},${y}`);
    const xs = comp.map(p => p[0]), ys = comp.map(p => p[1]), x0 = Math.min(...xs), x1 = Math.max(...xs), y0 = Math.min(...ys), y1 = Math.max(...ys);
    const cx = Math.round((x0 + x1) / 2), cy = Math.round((y0 + y1) / 2);
    if (def.crags !== false && comp.length >= 12 && x1 - x0 >= 2 && y1 - y0 >= 2 && rockSet.has(`${cx},${cy}`)) out.decor.push({ kind: 'crag', x: x0, y: y1, w: x1 - x0 + 1, h: y1 - y0 + 1 });
  }
  if (def.heights || def.levels) applyHeights(out, def);
  out.spawns.a ||= out.spawns.z; out.spawns.z ||= out.spawns.a;
  parsed.set(def.id, out);
  return out;
}

// 건물 안 한 층: 벽·바닥·문·계단, 가구(지나갈 수 없음), 숫자 칸의 물건과 사람.
function parseRoom(def) {
  const rows = def.art, grid = rows.map(() => Array(MAP_W).fill(TILE_CODES.VOID));
  const out = { def, grid, solid: new Set(), exits: new Map(), spawns: {}, buildings: [], decor: [], roles: {}, residents: {}, objects: [], rockTiles: new Set(), doors: [], stairs: [], focus: def.focus };
  const top = def.focus.y;
  for (let y = 0; y < MAP_H; y++) for (let x = 0; x < MAP_W; x++) {
    const c = rows[y][x], key = `${x},${y}`;
    if (c in ROOM_TERRAIN) {
      grid[y][x] = ROOM_TERRAIN[c];
      if (c === 'y') out.decor.push({ kind: 'window', x, y, wall: true });
      if (c === 'D') out.doors.push({ x, y });
      if (c === 'U' || c === 'N') out.stairs.push({ x, y, dir: c === 'U' ? 'up' : 'down' });
      if (c === 'a') out.spawns.a = { x, y };
      continue;
    }
    if (c in ROOM_FURNITURE) { grid[y][x] = rows[y].includes(',') ? TILE_CODES.STONE : TILE_CODES.FLOOR; out.solid.add(key); out.decor.push({ kind: ROOM_FURNITURE[c], x, y }); continue; }
    if (/[0-9]/.test(c) && def.objects?.[c]) {
      grid[y][x] = y === top ? TILE_CODES.WALL : rows[y].includes(',') ? TILE_CODES.STONE : TILE_CODES.FLOOR;
      out.objects.push({ key: c, x, y, ...def.objects[c] }); continue;
    }
    throw new Error(`${def.id}: unknown room letter '${c}' at ${x},${y}`);
  }
  // where you stand after using a door or stairs: the first free floor next to it (below first)
  const free = (x, y) => [10, 11, 12].includes(grid[y]?.[x]) && !out.solid.has(`${x},${y}`) && !out.objects.some(o => o.x === x && o.y === y);
  const beside = p => [[0, -1], [0, 1], [-1, 0], [1, 0]].map(([dx, dy]) => ({ x: p.x + dx, y: p.y + dy })).find(q => free(q.x, q.y));
  for (const s of out.stairs) s.land = beside(s);
  out.spawns.a ||= out.doors[0] ? beside(out.doors[0]) : out.stairs[0]?.land;
  out.spawns.z = out.spawns.a;
  return out;
}
